from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class PmtuDiscoveryTestResult(SchemaObject):
    local_mtu = SchemaField(name="local_mtu")
    path_mtu = SchemaField(name="path_mtu")

    def __init__(self, local_mtu, path_mtu):
        self.local_mtu = local_mtu
        self.path_mtu = path_mtu
        super(PmtuDiscoveryTestResult, self).__init__()


class PmtuDiscoveryStatusTRSV1(SchemaObject):
    status = SchemaField(name="status")
    reason = SchemaField(name="reason")
    result = SchemaField(name="result", klass=PmtuDiscoveryTestResult)

    def __init__(self, status, reason, result):
        self.status = status
        self.reason = reason
        self.result = result
        super(PmtuDiscoveryStatusTRSV1, self).__init__()
